changes=json.loads("[[\"async function logout(){\\n try{\\n  if(mode==='live'&&C.session){\\n   if(syncBusy||queueBusy)throw Error('توجد مزامنة جارية؛ انتظر اكتمالها قبل تبديل المتجر.');\\n   const saved=await P7Store.get('queue:'+C.session.user.id)||[];\\n   const unfinished=[...queue,...saved].filter(x=>x&&['queued','sent','pending'].includes(x.status));\\n   if(unfinished.length)throw Error('يوجد '+unfinished.length+' حركات لم تُعتمد بعد. لا يمكن تبديل المتجر قبل إكمالها لحماية بياناتك.');\\n   // A separate inventory sender stores counts and batches outside the owner command queue.\\n   let inventoryCount, inventoryBatch;\\n   try{\\n    inventoryCount=JSON.parse(window.P7Local.getItem('pos7-r71-count:'+C.session.user.id)||'{}');\\n    inventoryBatch=JSON.parse(window.P7Local.getItem('pos7-r105-transfer:'+C.session.user.id)||'null');\\n   }catch(e){throw Error('تعذر فحص بيانات الجرد المحلية؛ لن نبدل المتجر حفاظاً عليها.');}\\n   // Saved counted quantities are a store-scoped draft, not evidence of an in-flight transfer.\\n   // Keep the draft untouched when switching accounts; active batches are blocked below.\\n   if(inventoryCount && (typeof inventoryCount!=='object' || Array.isArray(inventoryCount)))\\n    throw Error('صيغة الجرد المحلي غير صحيحة؛ لن نبدل المتجر حتى مراجعة السجل.');\\n   // R254: a persisted inventory batch belongs to the current store and must remain\\n   // stored there across logout; it is NOT proof that network transmission is active.\\n   // Only prevent logout while the actual inventory sender is running.\\n   if(document.querySelector('#r71-transfer:disabled')||window.POS7R255ResetBusy)\\n    throw Error('يجري إرسال دفعة الجرد الآن؛ أكمل عملية الإرسال قبل تبديل المتجر.');\\n   if(document.querySelector('#pos134-sync:disabled'))throw Error('يجري رفع صورة منتج؛ لا تبدّل المتجر أثناء الإرسال.');\\n   if(!navigator.onLine)throw Error('يجب الاتصال بالإنترنت لإلغاء ربط الإشعارات قبل التبديل.');\\n   await unregisterPushDevice(); // Failed unregister blocks switch, rather than silently mixing push tokens.\\n  }\\n  epoch++;\\n  if(window.Pos7Android?.clearPushOwner)window.Pos7Android.clearPushOwner();\\n  C.session=null;\\n  window.P7Local.removeItem('POS7_OWNER_SESSION');\\n  s=null;ix=null;mode='';queue=[];orders=[];phoneNotifications=[];pendingPushOpen=null;updateNotificationBadge();scope='';close();if(typeof window.POS7PhotoResetUI==='function')window.POS7PhotoResetUI();window.POS7InventoryResetUI?.();window.POS7R73Camera?.stop();for(const id of ['r71-panel','r75-modal','pos134-modal','r198-report']){const panel=document.getElementById(id);if(panel)panel.style.display='none';}loginScreen();window.scrollTo(0,0);msg('تم الخروج من '+window.P7Multi.label+'؛ يمكن دخول المتجر الآخر الآن');\\n }catch(e){const reason='تعذر تبديل المتجر: '+(e?.message||String(e));notify(reason);window.alert(reason+'\\\\n\\\\nلم تُحذف جلسة الدخول أو بيانات الجرد أو الحركات.');}\\n}\\n\",\"// R257: merge only one authenticated store's durable queue. Never invent a server ACK.\\nfunction r257Canonical(v){return JSON.stringify(v,(k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(p=>[p,x[p]])):x)}\\nfunction r257MergeQueue(memory,saved,uid){\\n const rank={queued:0,sent:1,pending:2,processed:3,rejected:3},out=new Map();\\n if(!Array.isArray(memory)||!Array.isArray(saved)||!uid)throw Error('سجل الحركات غير صالح');\\n for(const x of [...saved,...memory]){\\n  if(!x||typeof x.event_id!=='string'||!x.event_id||x.owner!==uid||!Object.hasOwn(rank,x.status)||!x.payload||typeof x.event_type!=='string')throw Error('هوية حركة محلية غير مؤكدة؛ لم تُحذف أي بيانات');\\n  const prev=out.get(x.event_id);\\n  if(!prev){out.set(x.event_id,x);continue;}\\n  for(const k of ['owner','event_type','device_id','payload','created_at'])if(r257Canonical(prev[k])!==r257Canonical(x[k]))throw Error('معرّف حركة مكرر ببيانات مختلفة؛ يلزم المراجعة');\\n  if(rank[prev.status]===3&&rank[x.status]===3&&(prev.status!==x.status||(prev.result!=null&&x.result!=null&&r257Canonical(prev.result)!==r257Canonical(x.result))))throw Error('نتائج اعتماد محلية متعارضة؛ يلزم المراجعة');\\n  const winner=rank[x.status]>=rank[prev.status]?x:prev,loser=winner===x?prev:x;\\n  out.set(x.event_id,{...loser,...winner,result:winner.result??(winner.status===loser.status?loser.result:undefined)});\\n }\\n return [...out.values()];\\n}\\nasync function logout(){\\n if(window.POS7R257SwitchBusy)return;\\n window.POS7R257SwitchBusy=true;\\n try{\\n  if(mode==='live'&&C.session){\\n   if(syncBusy||queueBusy||financialSubmitBusy||C.refreshing)throw Error('توجد مزامنة جارية؛ انتظر اكتمالها قبل تبديل المتجر.');\\n   const uid=C.session.user.id,project=window.P7Multi.ref,url=C.url,e=epoch,storeKey='queue:'+uid;\\n   const same=()=>epoch===e&&C.session?.user?.id===uid&&window.P7Multi.ref===project&&C.url===url;\\n   const saved=await P7Store.get(storeKey)||[];\\n   if(!same())throw Error('تغيّر حساب المتجر أثناء الحفظ');\\n   const merged=r257MergeQueue(queue,saved,uid);\\n   await P7Store.put(storeKey,merged);\\n   const durable=await P7Store.get(storeKey);\\n   if(!same()||r257Canonical(durable)!==r257Canonical(merged))throw Error('تعذر التحقق من حفظ الحركات في متجرها الأصلي');\\n   queue=merged;\\n   const unfinished=merged.filter(x=>['queued','sent','pending'].includes(x.status));\\n   if(unfinished.length)msg('تم حفظ '+unfinished.length+' حركة في المتجر الحالي؛ ستُستكمل عند العودة إليه.');\\n   // A separate inventory sender stores counts and batches outside the owner command queue.\\n   let inventoryCount, inventoryBatch;\\n   try{\\n    inventoryCount=JSON.parse(window.P7Local.getItem('pos7-r71-count:'+C.session.user.id)||'{}');\\n    inventoryBatch=JSON.parse(window.P7Local.getItem('pos7-r105-transfer:'+C.session.user.id)||'null');\\n   }catch(e){throw Error('تعذر فحص بيانات الجرد المحلية؛ لن نبدل المتجر حفاظاً عليها.');}\\n   // Saved counted quantities are a store-scoped draft, not evidence of an in-flight transfer.\\n   // Keep the draft untouched when switching accounts; active batches are blocked below.\\n   if(inventoryCount && (typeof inventoryCount!=='object' || Array.isArray(inventoryCount)))\\n    throw Error('صيغة الجرد المحلي غير صحيحة؛ لن نبدل المتجر حتى مراجعة السجل.');\\n   // R254: a persisted inventory batch belongs to the current store and must remain\\n   // stored there across logout; it is NOT proof that network transmission is active.\\n   // Only prevent logout while the actual inventory sender is running.\\n   if(document.querySelector('#r71-transfer:disabled')||window.POS7R255ResetBusy)\\n    throw Error('يجري إرسال دفعة الجرد الآن؛ أكمل عملية الإرسال قبل تبديل المتجر.');\\n   if(document.querySelector('#pos134-sync:disabled'))throw Error('يجري رفع صورة منتج؛ لا تبدّل المتجر أثناء الإرسال.');\\n   if(!navigator.onLine)throw Error('يجب الاتصال بالإنترنت لإلغاء ربط الإشعارات قبل التبديل.');\\n   await unregisterPushDevice(); // Failed unregister blocks switch, rather than silently mixing push tokens.\\n   if(!same())throw Error('تغيّر حساب المتجر أثناء تسجيل الخروج');\\n  }\\n  epoch++;\\n  if(window.Pos7Android?.clearPushOwner)window.Pos7Android.clearPushOwner();\\n  C.session=null;\\n  window.P7Local.removeItem('POS7_OWNER_SESSION');\\n  s=null;ix=null;mode='';selection=null;queue=[];orders=[];phoneNotifications=[];pendingPushOpen=null;updateNotificationBadge();scope='';close();if(typeof window.POS7PhotoResetUI==='function')window.POS7PhotoResetUI();window.POS7InventoryResetUI?.();window.POS7R73Camera?.stop();for(const id of ['r71-panel','r75-modal','pos134-modal','r198-report']){const panel=document.getElementById(id);if(panel)panel.style.display='none';}loginScreen();window.scrollTo(0,0);msg('تم الخروج من '+window.P7Multi.label+'؛ يمكن دخول المتجر الآخر الآن');\\n }catch(e){const reason='تعذر تبديل المتجر: '+(e?.message||String(e));notify(reason);window.alert(reason+'\\\\n\\\\nلم تُحذف جلسة الدخول أو بيانات الجرد أو الحركات.');}finally{window.POS7R257SwitchBusy=false;}\\n}\\n\"],[\"async function submit(){if(mode!=='live'\",\"let financialSubmitBusy=false;\\nasync function submit(){if(window.POS7R257SwitchBusy||financialSubmitBusy)return notify('انتظر انتهاء العملية الحالية');if(mode!=='live'\"],[\"buttonEl.disabled=true;try{const uid=C.session.user.id,event=\",\"buttonEl.disabled=true;financialSubmitBusy=true;try{const uid=C.session.user.id,event=\"],[\"finally{buttonEl.disabled=false}}\\nfunction uuid()\",\"finally{financialSubmitBusy=false;buttonEl.disabled=false}}\\nfunction uuid()\"],[\"async function syncQueue(){if(queueBusy||\",\"async function syncQueue(){if(window.POS7R257SwitchBusy||queueBusy||\"],[\"async function refresh(){if(mode!=='live')\",\"async function refresh(){if(window.POS7R257SwitchBusy)return;if(mode!=='live')\"],[\"async function run(add){if(busy||window.POS7R255ResetBusy)return;\",\"async function run(add){if(window.POS7R257SwitchBusy||busy||window.POS7R255ResetBusy)return;\"],[\"$('pos134-sync').onclick=async()=>{\",\"$('pos134-sync').onclick=async()=>{\\n if(window.POS7R257SwitchBusy)return;\"],[\"function runDataAction(b){if(!b||b.disabled||!actions[b.dataset.action])return;Promise.resolve().then(()=>actions[b.dataset.action](b.dataset.id))\",\"function runDataAction(b){if(window.POS7R257SwitchBusy||!b||b.disabled||!actions[b.dataset.action])return;Promise.resolve().then(()=>{if(!window.POS7R257SwitchBusy)return actions[b.dataset.action](b.dataset.id)})\"]]")
